/**
 * source-classifier.mjs — Claude 資源來源分類器
 *
 * 提供共用的 parseSource / parseSourceFromContent 函式，
 * 供 usage-scanner.mjs、resources.mjs 等模組統一呼叫。
 *
 * 來源判斷優先順序：
 *   1. HTML comment 標記「generated by ab-tao::ecc」     → "ecc"
 *   2. HTML comment 標記「generated by ab-tao::anthropic」→ "anthropic"
 *   3. YAML frontmatter origin: ECC | ecc               → "ecc"
 *   4. YAML frontmatter origin: Anthropic | anthropic   → "anthropic"
 *   5. YAML frontmatter origin: ab-tao                  → "ab-tao"
 *   6. Markdown 標題「# Generated by ab-tao」或 HTML comment「generated by ab-tao」→ "ab-tao"
 *   7. 無任何標記                                         → "custom"
 */

import fs from "node:fs";

/**
 * 從已讀取的檔案前綴字串判斷資源來源（純函式，無 I/O）
 *
 * @param {string} headContent - 檔案前 1024 bytes 的字串內容
 * @returns {"ecc"|"anthropic"|"ab-tao"|"custom"}
 */
export function parseSourceFromContent(headContent) {
	// 1 & 2：HTML comment 標記（含 source 子串）
	const htmlCommentMatch = headContent.match(
		/<!--\s*generated by ab-tao(?:::([^\s>]+))?\s*-->/,
	);
	if (htmlCommentMatch) {
		const source = htmlCommentMatch[1]?.toLowerCase();
		if (source === "ecc") return "ecc";
		if (source === "anthropic") return "anthropic";
		// 有 comment 但無子串 → ab-tao（見下方第 6 條統一處理）
	}

	// 3 & 4 & 5：YAML frontmatter 的 origin 欄位
	const originMatch = headContent.match(/^origin:\s*(\S+)/m);
	if (originMatch) {
		const origin = originMatch[1].toLowerCase();
		if (origin === "ecc") return "ecc";
		if (origin === "anthropic") return "anthropic";
		if (origin === "ab-tao") return "ab-tao";
	}

	// 6：Markdown 標題 or HTML comment（無子串的 ab-tao 標記）
	if (
		htmlCommentMatch || // 上方 step 1/2 已命中 comment（無子串的情況落到此）
		/^#\s*Generated by ab-tao/m.test(headContent)
	) {
		return "ab-tao";
	}

	// 7：無任何標記
	return "custom";
}

/**
 * 從檔案前 1KB 內容判斷資源來源
 *
 * @param {string} filePath - 檔案絕對路徑
 * @returns {"ecc"|"anthropic"|"ab-tao"|"custom"}
 */
export function parseSource(filePath) {
	try {
		// 只讀取前 1024 bytes，避免掃描大型檔案造成效能問題
		const fd = fs.openSync(filePath, "r");
		const buf = Buffer.alloc(1024);
		const bytesRead = fs.readSync(fd, buf, 0, 1024, 0);
		fs.closeSync(fd);
		const head = buf.slice(0, bytesRead).toString("utf8");
		return parseSourceFromContent(head);
	} catch {
		// 讀取失敗（檔案不存在、權限問題等）→ 回傳預設值
		return "custom";
	}
}
